import React from "react";
import { X } from "lucide-react";
import { COLORS } from "../constants/theme";

const LINKS = ["Rings", "Necklaces", "Earrings"];

const TEXT = COLORS.text || "#141422";
const MUTED = COLORS.textMuted || "#6b6f7a";
const BORDER = COLORS.border || "#e4e4e8";
const BG = COLORS.surfaceBase || "#ffffff";

export default function MobileDrawer({ menuOpen, setMenuOpen, scrollTo, width = 280 }) {
  const handleNav = (id) => {
    scrollTo(id);
    setMenuOpen(false);
  };

  const linkStyle = {
    display: "block",
    width: "100%",
    textAlign: "left",
    padding: "20px 0",
    background: "none",
    border: "none",
    borderBottom: `1px solid ${BORDER}`,
    fontSize: 17,
    fontWeight: 500,
    color: TEXT,
  };

  return (
    // "nyasa-mobile-only" instead of "md:hidden" — global.css has a rule
    // (`.md\:hidden { width: 64px !important; ... }`) written for a mobile
    // collection icon that collides with Tailwind's generic hide-on-desktop
    // utility. Using our own class name sidesteps that collision entirely.
    <div
      role="navigation"
      aria-label="Mobile menu"
      className="nyasa-mobile-only"
      aria-hidden={!menuOpen}
      style={{
        position: "fixed",
        top: 30,
        left: 0,
        width,
        height: "100vh",
        background: BG,
        zIndex: 1,
        overflowY: "auto",
        boxSizing: "border-box",
      }}
    >
      <div className="flex items-center justify-between px-6" style={{ height: 64, borderBottom: `1px solid ${BORDER}` }}>
        <span style={{ fontSize: 13, letterSpacing: "0.08em", color: MUTED, textTransform: "uppercase", fontWeight: 600 }}>
          Menu
        </span>
        <button
          onClick={() => setMenuOpen(false)}
          aria-label="Close menu"
          tabIndex={menuOpen ? 0 : -1}
          style={{ background: "none", border: "none", color: TEXT, padding: 8 }}
        >
          <X size={20} strokeWidth={1.8} />
        </button>
      </div>

      <div className="flex flex-col px-6" style={{ paddingTop: 8 }}>
        {LINKS.map((c) => (
          <button key={c} onClick={() => handleNav("shop")} tabIndex={menuOpen ? 0 : -1} style={linkStyle}>
            {c}
          </button>
        ))}
        <button onClick={() => handleNav("craft")} tabIndex={menuOpen ? 0 : -1} style={linkStyle}>
          The Craft
        </button>
        <button onClick={() => handleNav("faq")} tabIndex={menuOpen ? 0 : -1} style={{ ...linkStyle, borderBottom: "none" }}>
          FAQ
        </button>
      </div>
    </div>
  );
}
